882	\begin{lemma}\label{lem:qld-xz-lines}
883	  There exists a function $\delta_P(\eps,m,d,q) = \poly(\eps,
884	  md/q)$ such that the following holds. For $\mH \in \{\mH_\alice,\mH_\bob\}$ and for every pair of lines $\line_X$ and $\line_Z$ there exists a POVM $\{T^{\line_X, \line_Z}_{f_X, f_Z}\}$ acting on
885	  $\mathcal{H} \otimes (\C^q)^{\otimes \nqubits}$ with answers
886	  consisting of pairs of polynomials $f_X, f_Z$ in $\deg_{md}(\line_X)
887	  \times \deg_{md}(\line_Z)$
888	  such that on average over pairs $(\line_X, x)$ and $(\line_Z, z)$
889	  independently sampled from the line-point distribution,
890	  \begin{align*}
891	    (T^{\line_X, \line_Z}_{[ \eval_x(\cdot) =a, \eval_z(\cdot) = b]})_{\alice \alice'} &\simeq_{\delta_P} (\hat{Q}^{x,z}_{a, b})_{\bob \alice''}, \\
892	\end{align*}
893	  as well as all symmetric equivalents of this approximation. Moreover, if $\line_W$ is axis-parallel, then $f_W \in \deg_{d}(\line_W)$.
894	\end{lemma}
895	
896	\begin{proof}
897	  We construct the required measurements by combining the measurements
898	  $\hat{M}^{(\Line,W),\line_W}_{f_W}$ for $W \in \{X, Z\}$. For convenience in the proof we slightly abuse the notation $\approx_\delta$ to mean $\approx_{\poly(\eps)}$ for some polynomial function $\delta=\poly(\eps)$ that may differ each time the notation is used.
899	
900	  	We first argue that the measurements $\{ \hat{Q}^{x,z}_{a,b} \}$ obtained in Lemma~\ref{lem:qld-4-10} are consistent with the $\{\hat{M}^{(\Line,W),\line_W}_{f_W} \}$. 
901	
902		Applying Fact~\ref{fact:add-a-proj} to~\eqref{eq:qld-q-cons-m-hat-zx}, we get that on average over uniformly random $x,z$,
903		\begin{align}
904			\Big( \hat{Q}^{x,z}_{a,b} \Big)_{\alice \alice'} \cdot \Big( \hat{M}^{(\Point,\zpt),z}_{b} \Big)_{\bob \alice''}
905	&=	\Big( \hat{M}^{(\Point,\zpt),z}_{b} \Big)_{\bob \alice''}\cdot	\Big( \hat{Q}^{x,z}_{a,b} \Big)_{\alice \alice'} \notag\\
906	& \approx_\delta \Big (\hat{M}^{(\Point,\zpt),z}_{b} \hat{M}^{(\Point,\xpt),x}_{a} \Big)_{\bob \alice''} \notag\\
907	&\approx_\delta \Big( \hat{Q}^{x,z}_{a,b} \Big)_{\alice \alice'}\;.\notag
908		\end{align}
909		Since $\{\hat{Q}^{x,z}_{a,b}\}$ is a projective measurement, applying \Cref{lem:cool-closeness-fact} with $(\hat{Q}^{x,z}_{a,b})_{\alice, \alice'}$ playing the role of $A^{x}_a$ and $(\hat{Q}^{x,z}_{a,b} )_{\alice, \alice'} \cdot (\hat{M}^{(\Point, \zpt), z}_{b})_{\bob \alice''}$ playing the role of $B^{x}_a$, we obtain that
910		\begin{equation}
911		\Big( \hat{Q}^{x,z}_{a} \Big)_{\alice \alice'} \approx_\delta \sum_b \Big( \hat{Q}^{x,z}_{a,b} \Big)_{\alice \alice'} \cdot \Big( \hat{M}^{(\Point,\zpt),z}_{b} \Big)_{\bob \alice''}\;.\label{eq:qqm}
912		\end{equation}
913		We now show that on average over uniformly random $x,z$, 
914		\begin{equation}
915		\label{eq:qld-qxz-close-to-point}
916		\Big ( \hat{Q}^{x,z}_{a} \Big)_{\alice \alice'} \approx_{\delta_Q} \Big (\hat{M}^{(\Point,X),x}_{a} \Big)_{\bob \alice''} \;.
917		\end{equation}
918		This follows from~\eqref{eq:qqm} and the following calculation:
919		\begin{align*}
920			&\E_{x,z} \sum_a \norm{ \sum_b  \Big( \hat{Q}^{x,z}_{a,b} \Big)_{\alice \alice'} \cdot \Big ( \hat{M}^{(\Point,\zpt),z}_{b} \Big)_{\bob \alice''} - \Big ( \hat{M}^{(\Point,\xpt),x}_{a} \Big)_{\bob \alice''}  \ket{\hat{\psi}} }^2  \\
921			&=\E_{x,z} \sum_a \norm{ \sum_b \Big ( \hat{M}^{(\Point,\zpt),z}_{b} \Big)_{\bob \alice''} \cdot  \Big( \Big( \hat{Q}^{x,z}_{a,b} \Big)_{\alice \alice'} - \Big ( \hat{M}^{(\Point,\xpt),x}_{a} \Big)_{\bob \alice''}  \Big) \ket{\hat{\psi}} }^2  \\
922			&= \E_{x,z} \sum_{a,b}  \norm{  \Big ( \hat{M}^{(\Point,\zpt),z}_{b} \Big)_{\bob \alice''} \cdot  \Big( \Big( \hat{Q}^{x,z}_{a,b} \Big)_{\alice \alice'} - \Big ( \hat{M}^{(\Point,\xpt),x}_{a} \Big)_{\bob \alice''}  \Big) \ket{\hat{\psi}} }^2  \\
923	                &= \E_{x,z} \sum_{a,b} \norm{ \Big(  \hat{M}^{(\Point,\zpt),z}_{b} \Big)_{\bob \alice''} \cdot  \Big( \Big( \hat{Q}^{x,z}_{a,b} \Big)_{\alice \alice'} - \Big( \hat{M}^{(\Point, \zpt),z}_{b} \cdot \hat{M}^{(\Point,\xpt),x}_{a} \Big)_{\bob \alice''}  \Big) \ket{\hat{\psi}} }^2  \\
924	                &\leq \E_{x,z} \sum_{a,b} \norm{ \Big( \Big( \hat{Q}^{x,z}_{a,b} \Big)_{\alice \alice'} - \Big( \hat{M}^{(\Point, \zpt),z}_{b} \cdot \hat{M}^{(\Point,\xpt),x}_{a} \Big)_{\bob \alice''}  \Big) \ket{\hat{\psi}} }^2  \\
925			&= O(\delta)\;,
926		\end{align*} 
927		where the second line uses the property $\sum_b \hat{M}^{(\Point,\zpt),z}_b = I$, the third and fourth lines uses the projectivity of $\{ \hat{M}^{(\Point,\zpt),z}_{b} \}$, the fifth line uses $\hat{M}^{(\Point, \zpt), z}_{b} \leq I$, and the last line uses \Cref{eq:qld-q-cons-m-hat-zx}. This shows~\eqref{eq:qld-qxz-close-to-point}. A similar argument shows that
928		\begin{equation}\label{eq:qld-qxz-close-to-point-2}
929		\Big ( \hat{Q}^{x,z}_{b} \Big)_{\alice \alice'} \approx_{\delta_Q} \Big (\hat{M}^{(\Point,Z),z}_{b} \Big)_{\bob \alice''}\;.
930		\end{equation}
931		Next, from Lemma~\ref{lem:qld-comm-line-cons} we get that on average over $(\line_X,x)$ and $(\line_Z,z)$ sampled independently from the line-point distribution (\Cref{def:line-point-dist}),
932		\begin{gather}
933		(\hat{M}^{(\Line,X),\line_\xpt}_{[\eval_x(\cdot) = a]})_{\bob \alice''} \approx_\delta  (\hat{M}^{(\Point,\xpt),x}_{a})_{\bob \alice''} \;,\\
934		( \hat{M}^{(\Line,Z),\line_\zpt}_{[\eval_z(\cdot) = b]})_{\bob \alice''} \approx_\delta  (\hat{M}^{(\Point,\zpt),z}_{b})_{\bob \alice''}\;.
935		\end{gather}
936		where we used both the self-consistency of the line measurements (item 1 in Lemma~\ref{lem:qld-comm-line-cons}) as well as their consistency with the points measurements (item 3). To deduce both of these relations, we used \Cref{fact:agreement} to convert between $\approx$ and $\simeq$ distance, and \Cref{fact:data-processing} to sum over outcomes to the lines measurement. Since the $\{\hat{M}^{(\Line,W),\line}_f \}$ and $\{ \hat{Q}^{x,z}_{a,b} \}$ are projective, together with~\eqref{eq:qld-qxz-close-to-point} and~\eqref{eq:qld-qxz-close-to-point-2}
937		by Fact~\ref{fact:agreement} we get
938		\begin{align}\label{eq:pasting-q1}
939			\Big ( \hat{Q}^{x,z}_{a} \Big)_{\alice \alice'} \simeq_{\delta_Q} \Big (\hat{M}^{(\Line,\xpt),\line_\xpt}_{[\eval_x(\cdot) = a]} \Big)_{\bob \alice''} \qquad \text{and} \qquad \Big ( \hat{Q}^{x,z}_{b} \Big)_{\alice \alice'} \simeq_{\delta_Q} \Big (\hat{M}^{(\Line,\zpt),\line_\zpt}_{[\eval_z(\cdot) = b]} \Big )_{\bob \alice''} \;.
940		\end{align}
941	
942		For all lines $\line_\xpt,\line_\zpt$ and $(f_\xpt,f_\zpt) \in \deg_{md}(\line_\xpt) \times \deg_{md}(\line_\zpt)$ define the operator
943		\[
944			T^{\line_\xpt,\line_\zpt}_{f_\xpt,f_\zpt} = \hat{M}^{(\Line,\xpt),\line_\xpt}_{f_\xpt} \cdot \hat{M}^{(\Line,\zpt),\line_\zpt}_{f_\zpt}  \cdot \hat{M}^{(\Line,\xpt),\line_\xpt}_{f_\xpt} \;.
945		\]
946		Then the collection $\{ T^{\line_\xpt,\line_\zpt}_{f_\xpt,f_\zpt} \}$ forms a valid POVM. Moreover, by the fact that $\{\hat{M}^{(\Line, W), \line_W}_{f_W}\}$ comes from a valid strategy for the low-degree test, it holds that $f_W \in \deg_{d}(\line_W)$ whenver $\line_W$ is axis-parallel, and thus property holds for $T$ as well. 
947	
948	        It only remains to bound the consistency of $\{T^{\line_\xpt, \line_\zpt}_{f_\xpt, f_\zpt}\}$ with $\{\hat{Q}^{x,z}_{a,b}\}$. Using the following choices of measurements,
949		\begin{equation*}
950			``A^{x,y_1,y_2}_{a_1,a_2}" : \hat{Q}^{x,z}_{a,b} \;, \quad
951			``(G_1)^x_g" : \hat{M}^{(\Line,\xpt),\line_\xpt}_{f_\xpt} \;, \quad
952			``(G_2)^x_g" : \hat{M}^{(\Line,\zpt),\line_\zpt}_{f_\zpt} \;, \quad
953			``J^x_{g_1,g_2}": T^{\line_\xpt,\line_\zpt}_{f_\xpt,f_\zpt} \;,
954	              \end{equation*}
955		Then the hypotheses of \Cref{lem:pasting} hold, with $\delta$ in the lemma set to $\delta_Q$, and $\eta$ in the lemma set to $md/q$ (this follows from the Schwartz-Zippel lemma applied to the polynomials $f_X, f_Z$, which are of total degree at most $md$). Applying the lemma, we conclude that
956		\begin{equation}
957		\label{eq:qld-4-13-1}
958			\Big( \hat{Q}^{x,z}_{a,b} \Big)_{\alice \alice'} \simeq_{\delta_P} \Big( T^{\line_\xpt,\line_\zpt}_{[\eval_x(\cdot) = a, \eval_z(\cdot) = b]} \Big)_{\bob \alice''}\;,
959		\end{equation}
960		where $\delta_P = \poly(\eps,md/q)$ is the $\delta_{pasting}$ as given by Lemma~\ref{lem:pasting}, conditions~\eqref{eq:pasting-1} and~\eqref{eq:pasting-2} in the lemma are given by~\eqref{eq:pasting-q1} and~\eqref{eq:qld-q-self-cons} respectively, 
961		and the distribution over $(\ell_\xpt,\ell_\zpt)$ are two independently and uniformly chosen lines. This is a symmetric equivalent of the consistency relation in the conclusion of Lemma. Thus, by applying an identical argument with the appropriate modifications to the registers, all symmetric equivalents of this relation hold, establishing the conclusion of the Lemma.
